    public TaskSourceVerifierReviewService(DataSource data,TaskSourceVerifierSchema json,TaskSourceVerifierNormalizer normalizer,RuleExpression ruleEngine,ProjectSchema projects)throws Exception{this.ruleEngine=ruleEngine;this.projects=projects;db=new JdbcTemplate(data);db.setQueryTimeout(5);this.json=json;this.normalizer=normalizer;schemas=SchemaCatalogue.fromClasspath();}
    public static String coverageManifest()throws Exception{try(var in=Objects.requireNonNull(TaskSourceVerifierReviewService.class.getResourceAsStream("/task-source-verifier-coverage.schema.json"))){return WireValues.sha256(in.readAllBytes());}}
    public Produced produce(TaskSourceVerifierInvocationService.Terminal terminal,RunTokenAuthority.ActionRequest action)throws Exception {
        terminal.requireUnchanged();var input=terminal.input();requireAction(input,action);var i=input.input();var contract=input.evidenceContract();
        var blocks=terminal.output().required("blocks");if(blocks.size()!=1||!"text".equals(blocks.get(0).path("type").asText())||!blocks.get(0).path("text").isTextual())bad();
        var reads=terminal.reviewReadPins();same(terminal.sessionId(),text(reads,"session_id"));if(input.target().writerSessionIds().contains(terminal.sessionId()))deny();
        var sourceReads=new LinkedHashMap<DatasetProtocol.EvidenceRef,TaskSourceVerifierNormalizer.Read>();var sourceSchema=new TaskSourceReadReceiptSchema(new PermissionSchema());
        for(var r:reads.required("sources")){var ref=sourceSchema.evidence(r.required("evidence_ref"));if(!input.evidenceRefs().contains(ref)||sourceReads.put(ref,new TaskSourceVerifierNormalizer.Read(terminal.sessionId(),text(r,"receipt_id"),ref,bool(r,"access"),bool(r,"located"),bool(r,"complete")))!=null)bad();}
        var claimReads=new LinkedHashMap<String,List<TaskSourceVerifierNormalizer.Read>>();for(var c:input.target().claims().values()){
            var selected=new ArrayList<TaskSourceVerifierNormalizer.Read>();var seen=new HashSet<DatasetProtocol.EvidenceRef>();for(var l:c.evidenceLinks())if(seen.add(l.evidenceRef())&&sourceReads.containsKey(l.evidenceRef()))selected.add(sourceReads.get(l.evidenceRef()));claimReads.put(c.claimId(),selected);
        }
        var body=input.target().body();var sectionNodes=input.target().candidate().nodeManifest().stream().filter(n->n.kind()==ArtifactProtocol.NodeKind.SECTION).map(ArtifactProtocol.NodeManifestItem::nodeId).toList();if(sectionNodes.isEmpty())bad();
        JsonNode anchorNode=null;for(var n:body.required("nodes"))if(sectionNodes.get(0).equals(text(n,"node_id")))anchorNode=n;if(anchorNode==null)bad();
        var anchor=new ArtifactProtocol.StructuredAnchor("STRUCTURED",sectionNodes.get(0),null,null,json.hash(anchorNode));var required=new LinkedHashMap<String,TaskSourceVerifierNormalizer.Rule>();
        var replay=input.production().replay().content();var completionRules=new LinkedHashSet<String>();for(var question:replay.required("plan").required("content").required("questions"))if(i.targetSections().contains(text(question,"section_id")))for(var r:question.required("completion_rule_ids"))completionRules.add(r.asText());
        var attributes=projects.attributes(replay.required("project_profile").required("attributes"));
        for(var r:input.rules().rules()){
            ArtifactProtocol.RuleResult deterministic=null;
            if(completionRules.contains(r.ruleId())){var evaluated=TaskResearchCompletionChecks.evaluate(ruleEngine,r.ruleId(),List.copyOf(completionRules),r.content(),attributes);deterministic=switch(evaluated.outcome()){case SATISFIED->ArtifactProtocol.RuleResult.PASS;case NOT_SATISFIED->ArtifactProtocol.RuleResult.FAIL;case UNKNOWN->ArtifactProtocol.RuleResult.BLOCKED;};}
            required.put(r.ruleId(),new TaskSourceVerifierNormalizer.Rule(r.ruleId(),sectionNodes,anchor,deterministic));
        }
        var readRules=new LinkedHashSet<String>();for(var r:reads.required("rule_ids")){if(!r.isTextual()||!required.containsKey(r.textValue())||!readRules.add(r.textValue()))bad();}
        var fixed=new TaskSourceVerifierNormalizer.Fixed(i.bodyArtifactId(),i.bodyObject().sha256(),i.ruleRevision(),terminal.sessionId(),input.target().writerSessionIds(),body,input.target().claims(),required,claimReads,readRules,Set.copyOf(input.evidenceRefs()));
        var normalized=normalizer.normalize(fixed,action.actionId(),json.read(blocks.get(0).required("text").textValue()),contract.artifactRef("ReviewFindings"),contract.artifactSha());
        normalized=RegulatoryComparisonPipeline.attach(normalized,RegulatoryComparisonPipeline.produce(input.regulatoryComparison(),input,reads,ruleEngine,projects));
        normalized=ReportScenarioPipeline.attach(normalized,ReportScenarioPipeline.produce(input,reads));
        normalized=ProductTechnicalRequirementPipeline.attach(normalized,ProductTechnicalRequirementPipeline.produce(input,reads));
        normalized=RegistrationDossierPipeline.attach(normalized,RegistrationDossierPipeline.produce(input,reads));
        normalized=NonclinicalPrinciplesRiskPipeline.attach(normalized,NonclinicalPrinciplesRiskPipeline.produce(input,reads));
        normalized=ClinicalEvaluationPipeline.attach(normalized,ClinicalEvaluationPipeline.produce(input,reads));
        normalized=RegistrationLifecyclePipeline.attach(normalized,RegistrationLifecyclePipeline.produce(input,reads));
        normalized=InstructionsLabelPipeline.attach(normalized,InstructionsLabelPipeline.produce(input,reads));
        normalized=MultimodalQaPipeline.attach(normalized,MultimodalQaPipeline.produce(input,reads,normalized.findings()));
        normalized=TranslationScenarioPipeline.attach(normalized,TranslationScenarioPipeline.produce(input,reads,normalized.findings()));
        normalized=MarketAnalysisScenarioPipeline.attach(normalized,MarketAnalysisScenarioPipeline.produce(input,reads,normalized.findings()));
        var output=new ArtifactProtocol.ReviewOutput("REVIEW_FINDINGS",normalized.findings());
        var artifact=new ArtifactProtocol.ProfessionalArtifact(contract.version(),ArtifactProtocol.ExecutionKind.TASK,i.tenantId(),i.projectId(),i.runId(),i.stepId(),input.inputSha256(),i.planRevision(),i.snapshotId(),i.targetSections(),TaskSourceVerifierObjectLedger.plannedAccessSet(i,action.actionId(),"REVIEW_FINDINGS"),json.hash(output),output);
        ArtifactEvidenceBindings.bind(schemas,ArtifactBindings.ARTIFACT,json.tree(artifact),contract.artifactRef(null),contract.artifactSha()).read();return new Produced(terminal,action,normalized,"REVIEW_FINDINGS",json.bytes(artifact));
    }
    public Produced coverage(Produced findings)throws Exception {
        findings.requireUnchanged();var input=findings.input();var i=input.input();var payload=JsonNodeFactory.instance.objectNode().put("schema_version","1.0.0").put("node_kind","N05").put("input_sha256",input.inputSha256()).put("session_id",findings.terminal.sessionId()).put("target_revision",i.bodyArtifactId()).put("target_sha256",i.bodyObject().sha256()).put("rule_revision",i.ruleRevision()).put("findings_sha256",WireValues.sha256(findings.bytes)).put("coverage_complete",findings.normalized.findings().coverageComplete());
        payload.set("required_claim_ids",json.tree(i.requiredClaimIds()));payload.set("required_rule_ids",json.tree(i.requiredRules().stream().map(PermissionProtocol.Basis::version_id).toList()));payload.set("checks",findings.normalized.pins().required("coverage"));payload.set("independent_reads",findings.terminal.reviewReadPins());
        json.coverage(payload);return new Produced(findings.terminal,findings.action,findings.normalized,"REVIEW_COVERAGE",json.bytes(payload));
    }
