        MarketAnalysisScenarioPipeline.consume(input,coverage.receipt.required("provenance"),findings);
        same(i.tenantId(),full.tenantId());same(i.projectId(),full.projectId());same(i.runId(),full.runId());same(i.stepId(),full.stepId());same(i.planRevision(),full.planRevision());same(i.snapshotId(),full.snapshotId());same(input.inputSha256(),full.inputManifestSha256());same(i.targetSections(),full.targetSectionIds());same(json.hash(full.output()),full.contentSha256());same(saved.accessSet,full.dependencyAccessSetId());
        same(ArtifactProtocol.TargetKind.CANDIDATE,findings.targetKind());same(i.bodyArtifactId(),findings.targetRevision());same(i.bodyObject().sha256(),findings.targetSha256());same(i.ruleRevision(),findings.ruleRevision());same(i.requiredClaimIds(),findings.requiredClaimIds());same(i.requiredRules().stream().map(PermissionProtocol.Basis::version_id).toList(),findings.requiredRuleIds());
        same(saved.object.sha256(),text(coverage.payload,"findings_sha256"));same(input.inputSha256(),text(coverage.payload,"input_sha256"));same(findings.coverageComplete(),bool(coverage.payload,"coverage_complete"));same(saved.receipt.required("provenance").required("session_id"),coverage.payload.required("session_id"));
        var prior=db.queryForList("SELECT * FROM task_source_verifier_submission WHERE tenant_id=? AND run_id=? AND step_id=? AND action_id=? LIMIT 2 FOR UPDATE",i.tenantId(),i.runId(),i.stepId(),action.actionId());if(!prior.isEmpty())return originalSubmission(input,saved,coverage,one(prior));
        var marks=one(db.queryForList("SELECT issue_watermark,evidence_watermark FROM document_revision_state WHERE tenant_id=? AND project_id=? AND document_revision=? LIMIT 2 FOR UPDATE",i.tenantId(),i.projectId(),input.target().candidate().baseDocumentRevision()));
        boolean blocked=!findings.coverageComplete()||!findings.issueProposals().isEmpty()||findings.claimChecks().stream().anyMatch(c->c.supportCheck()==ArtifactProtocol.SupportCheck.CONTRADICTED||c.supportCheck()==ArtifactProtocol.SupportCheck.INSUFFICIENT)||findings.ruleChecks().stream().anyMatch(r->r.result()==ArtifactProtocol.RuleResult.FAIL||r.result()==ArtifactProtocol.RuleResult.BLOCKED);
