        for(int n=0;n<findings.issueProposals().size();n++){var proposal=meta(input,at);proposal.putAll(Map.of("proposal_id",proposalIds.get(n),"check_id",check,"candidate_id",i.candidateId(),"target_revision",i.bodyArtifactId(),"proposal_json",json.canonical(findings.issueProposals().get(n)),"proposal_sha256",json.hash(findings.issueProposals().get(n)),"status","OPEN"));insert("task_source_verifier_issue_proposal",proposal);}
