        var log=meta(input,at);log.putAll(Map.of("audit_id",audit,"subject_id",input.production().actorId(),"action","task.source_verifier.review.submitted","resource_ref",json.canonical(receipt),"result","SUCCESS","request_id",action.actionId(),"trace_id",i.runId()));insert("audit_event",log);insert("outbox_event",Map.of("tenant_id",i.tenantId(),"event_id",event,"aggregate_id",check,"aggregate_revision",1,"event_type","candidate.review.recorded","payload",json.canonical(receipt),"occurred_at",at));insert("task_source_verifier_submission",record);
        current.requireUnchanged();return originalSubmission(input,saved,coverage,one(db.queryForList("SELECT * FROM task_source_verifier_submission WHERE tenant_id=? AND check_id=? LIMIT 2 FOR UPDATE",i.tenantId(),check)));
