    private void journal(TaskSourceVerifierInputAuthority.Verified input,JsonNode receipt)throws Exception {var a=one(db.queryForList("SELECT resource_ref,result,subject_id FROM audit_event WHERE tenant_id=? AND audit_id=? LIMIT 2 FOR UPDATE",input.tenantId(),text(receipt,"audit_id")));same("SUCCESS",str(a,"result"));same(input.production().actorId(),str(a,"subject_id"));same(receipt,json.read(str(a,"resource_ref")));var e=one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? LIMIT 2 FOR UPDATE",input.tenantId(),text(receipt,"event_id")));same(receipt,json.read(str(e,"payload")));}
