    private void requireAction(TaskSourceVerifierInputAuthority.Verified input,RunTokenAuthority.ActionRequest a)throws Exception {
        input.requireUnchanged();var i=input.input();var scope=new PermissionProtocol.Scope(i.tenantId(),i.projectId(),"TASK",i.taskId());if(!"TOOL".equals(a.kind())||!ACTION.equals(a.action())||!PURPOSE.equals(a.purpose())||!scope.equals(a.scope())||!i.submitToolVersion().version_id().equals(a.toolVersion())||!i.runId().equals(a.runId())||!i.stepId().equals(a.stepId())||!input.inputSha256().equals(a.inputSha256())||!i.nodePermissions().contains(new RunTokenAuthoritySchema.Permission(scope,ACTION,PURPOSE)))deny();
        var rows=db.queryForList("SELECT b.action_id FROM step_action_binding b JOIN run_step s ON s.tenant_id=b.tenant_id AND s.project_id=b.project_id AND s.run_id=b.run_id AND s.step_id=b.step_id WHERE b.tenant_id=? AND b.project_id=? AND b.run_id=? AND b.step_id=? AND b.action_id=? AND b.kind='TOOL' AND b.tool_version=? AND b.arguments_sha256=? AND b.input_sha256=? AND b.lease_generation=? AND s.lease_generation=b.lease_generation AND s.status='RUNNING' AND s.lease_expires_at>UTC_TIMESTAMP(6) AND b.state IN ('BOUND','RESERVED','DISPATCHING','IN_FLIGHT') LIMIT 2 FOR UPDATE",i.tenantId(),i.projectId(),i.runId(),i.stepId(),a.actionId(),a.toolVersion(),a.argumentsSha256(),a.inputSha256(),a.generation());if(rows.size()!=1)deny();
    }
    public final class Produced {
        private final TaskSourceVerifierInputAuthority.Verified input;private final TaskSourceVerifierInvocationService.Terminal terminal;private final RunTokenAuthority.ActionRequest action;private final TaskSourceVerifierNormalizer.Normalized normalized;private final String kind;private final byte[] bytes;
        private Produced(TaskSourceVerifierInvocationService.Terminal t,RunTokenAuthority.ActionRequest a,TaskSourceVerifierNormalizer.Normalized n,String k,byte[] bytes)throws Exception{input=t.input();terminal=t;action=a;normalized=n;kind=k;this.bytes=bytes.clone();}
        public void requireUnchanged()throws Exception{terminal.requireUnchanged();requireAction(input,action);}
        public TaskSourceVerifierInputAuthority.Verified input(){return input;}public String schemaRef()throws Exception{return input.evidenceContract().artifactRef(null);}public String schemaHash()throws Exception{return input.evidenceContract().artifactSha();}
        public String actionId(){return action.actionId();}public String kind(){return kind;}public byte[] bytes()throws Exception{requireUnchanged();return bytes.clone();}
        public JsonNode provenance()throws Exception{requireUnchanged();var p=JsonNodeFactory.instance.objectNode().put("schema_version","1.0.0").put("node_kind","N05").put("action_id",actionId()).put("kind",kind).put("session_id",terminal.sessionId()).put("input_sha256",input.inputSha256()).put("input_receipt_sha256",input.receiptSha256()).put("payload_sha256",WireValues.sha256(bytes));p.set("invocations",terminal.canonicalPins());p.set("supervision",terminal.supervisionPins());p.set("normalization",normalized.pins());p.set("independent_reads",terminal.reviewReadPins());return p;}
    }
    private Map<String,Object> meta(TaskSourceVerifierInputAuthority.Verified input,LocalDateTime at)throws Exception{var m=new LinkedHashMap<String,Object>();m.put("tenant_id",input.tenantId());m.put("project_id",input.projectId());m.put("created_by",input.production().actorId());m.put("created_at",at);m.put("classification",input.production().classification());m.put("schema_version","1.0.0");m.put("schema_manifest_sha256",input.evidenceContract().artifactSha());return m;}
    private void insert(String table,Map<String,Object> values){var keys=new ArrayList<>(values.keySet());if(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(values::get).toArray())!=1)bad();}
    private LocalDateTime now(){return db.queryForObject("SELECT UTC_TIMESTAMP(6)",LocalDateTime.class);}private static String id(){return UUID.randomUUID().toString();}private static <T>T one(List<T> rows){if(rows.size()!=1)bad();return rows.get(0);}private static String str(Map<String,Object> row,String key){var v=row.get(key);if(v==null)bad();return v.toString();}private static String text(JsonNode n,String k){if(!n.required(k).isTextual())bad();return n.required(k).textValue();}private static boolean bool(JsonNode n,String k){if(!n.required(k).isBoolean())bad();return n.required(k).booleanValue();}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
